void rabinKarp(string text, string pattern) {
    int d=256, q=101;
    int n=text.length(), m=pattern.length();
    int h=1, p=0, t=0;
    bool found=false;
    for(int i=0;i<m-1;i++) h=(h*d)%q;
    for(int i=0;i<m;i++) { p=(d*p+pattern[i])%q; t=(d*t+text[i])%q; }
    for(int i=0;i<=n-m;i++) {
        if(p==t && text.substr(i,m)==pattern) {
            if(found) cout<<" "; cout<<i; found=true;
        }
        if(i<n-m) { t=(d*(t-text[i]*h)+text[i+m])%q; if(t<0) t+=q; }
    }
    if(!found) cout<<-1;
    cout<<endl;
}

