string shortestPalindrome(string s) {
    string rev = s;
    reverse(rev.begin(), rev.end());
    string concat = s + "#" + rev;
    int n = concat.length();
    vector<int> lps(n, 0);
    int len = 0, i = 1;
    while (i < n) {
        if (concat[i] == concat[len]) lps[i++] = ++len;
        else { if (len) len = lps[len-1]; else lps[i++] = 0; }
    }
    string prefix = rev.substr(0, s.length() - lps[n-1]);
    return prefix + s;
}

